1	import { createHighlighterCore } from "shiki/core";
2	import { createJavaScriptRegexEngine } from "shiki/engine/javascript";
3	import type { LanguageRegistration } from "@shikijs/types";
4	import DOMPurify from "dompurify";
5	import "./runner.css";
6	
7	type PartKey = "html" | "css" | "js";
8	
9	// Highlight the read-only source with Shiki, using the same themes the docs' `@example` fences do
10	// (VitePress's default `github-light` / `github-dark`), so a demo's code reads identically to the
11	// examples beside it. The one JavaScript RegExp engine (no WASM) plus the two small theme JSONs keep
12	// the runner light; each grammar is code-split and loaded only when a demo actually uses that language.
13	const langLoaders: Record<PartKey, () => Promise<LanguageRegistration[]>> = {
14	  html: () => import("@shikijs/langs/html").then((m) => m.default),
15	  css: () => import("@shikijs/langs/css").then((m) => m.default),
16	  js: () => import("@shikijs/langs/javascript").then((m) => m.default),
17	};
18	// Shiki's grammar id per part (JS's grammar is registered under "javascript").
19	const langId: Record<PartKey, string> = { html: "html", css: "css", js: "javascript" };
20	
21	const params = new URLSearchParams(location.search);
22	const cssUrls = (params.get("css") ?? "").split(",").filter(Boolean);
23	const srcUrl = params.get("src");
24	const mount = document.getElementById("runner");
25	
26	// A manual override (set by the host's light/dark toggle) wins over the inherited scheme; null means
27	// "follow the embedding page".
28	let schemeOverride: "light" | "dark" | null = null;
29	
30	/** The inherited scheme: the embedding page's `.dark`, else system (when opened top-level). */
31	function isDark(): boolean {
32	  try {
33	    if (window.parent && window.parent !== window) {
34	      return window.parent.document.documentElement.classList.contains("dark");
35	    }
36	  } catch {
37	    // Cross-origin parent.
38	  }
39	  return matchMedia("(prefers-color-scheme: dark)").matches;
40	}
41	/** The scheme actually rendered: the override if set, otherwise the inherited scheme. */
42	const effectiveDark = (): boolean => (schemeOverride ? schemeOverride === "dark" : isDark());
43	const schemeName = (): string => (effectiveDark() ? "dark" : "light");
44	
45	function fail(message: string): void {
46	  if (mount) mount.innerHTML = `<pre id="runner-error"></pre>`;
47	  const box = document.getElementById("runner-error");
48	  if (box) box.textContent = message;
49	}
50	
51	/** Copy `text` to the clipboard, falling back to a hidden textarea + `execCommand` where the async API
52	 * is unavailable (e.g. an insecure context). */
53	async function copyToClipboard(text: string): Promise<void> {
54	  try {
55	    await navigator.clipboard.writeText(text);
56	    return;
57	  } catch {
58	    // Fall through to the legacy path below.
59	  }
60	  const area = document.createElement("textarea");
61	  area.value = text;
62	  area.setAttribute("readonly", "");
63	  area.style.position = "absolute";
64	  area.style.left = "-9999px";
65	  document.body.appendChild(area);
66	  area.select();
67	  document.execCommand("copy");
68	  document.body.removeChild(area);
69	}
70	
71	/** De-indent a block: drop surrounding blank lines, then strip the smallest common leading indent. */
72	function dedent(text: string): string {
73	  const lines = text.replace(/^\n+/, "").replace(/\s+$/, "").split("\n");
74	  const indents = lines
75	    .filter((line) => line.trim())
76	    .map((line) => /^\s*/.exec(line)?.[0].length ?? 0);
77	  const min = indents.length ? Math.min(...indents) : 0;
78	  return lines.map((line) => line.slice(min)).join("\n");
79	}
80	
81	/** The demos wrap their markup in a staging `<div class="instui-card">` so the preview sits on a card,
82	 * like the docs' `@example` previews. That wrapper is page staging, not part of the component's own
83	 * markup, so strip it (and de-indent) for the code view — the result still renders the full source. */
84	function stripCardWrapper(html: string): string {
85	  const match = /^<div\s+class="instui-card(?:\s+[^"]*)?"\s*>\n?([\s\S]*?)\n?<\/div>\s*$/i.exec(
86	    html.trim(),
87	  );
88	  return match ? dedent(match[1]) : html;
89	}
90	
91	/** A hover-to-reveal copy button holding its own source `text`; toggles `.copied` for ~2s on success. */
92	function createCopyButton(text: string): HTMLButtonElement {
93	  const button = document.createElement("button");
94	  button.type = "button";
95	  button.className = "copy";
96	  button.title = "Copy code";
97	  button.setAttribute("aria-label", "Copy code");
98	  let resetTimer: ReturnType<typeof setTimeout> | undefined;
99	  button.addEventListener("click", () => {
100	    void copyToClipboard(text).then(() => {
101	      button.classList.add("copied");
102	      clearTimeout(resetTimer);
103	      resetTimer = setTimeout(() => {
104	        button.classList.remove("copied");
105	        button.blur();
106	      }, 2000);
107	    });
108	  });
109	  return button;
110	}
111	
112	async function main(): Promise<void> {
113	  if (!mount) return;
114	  if (!srcUrl) {
115	    fail("No demo source (missing ?src=).");
116	    return;
117	  }
118	
119	  // Show a spinner immediately and keep it until everything's ready — styles loaded, the demo rendered
120	  // and measured — then swap in the finished runner in one step, so the reader never sees the half-built
121	  // states (unstyled chrome, jumping heights) flash by. The spinner is styled by the bundled runner.css,
122	  // so it needs none of the async component sheets below.
123	  let booting = true;
124	  const loading = document.createElement("div");
125	  loading.className = "runner__loading";
126	  loading.setAttribute("role", "status");
127	  loading.setAttribute("aria-label", "Loading demo");
128	  loading.innerHTML = `<span class="runner__spinner"></span>`;
129	  mount.replaceChildren(loading);
130	  const postSize = (height: number): void => {
131	    if (window.parent !== window)
132	      window.parent.postMessage({ type: "pantoken-demo-size", height }, "*");
133	  };
134	  // Give the host a stable box to size to while we boot.
135	  postSize(Math.ceil(loading.getBoundingClientRect().height));
136	
137	  // Inject the component/token sheets, tracking when they've all loaded so the reveal can wait for them
138	  // (no unstyled flash). Everything reads paired --instui-* tokens, so it's dark-mode safe.
139	  const cssLoaded = Promise.all(
140	    cssUrls.map(
141	      (href) =>
142	        new Promise<void>((resolve) => {
143	          const link = document.createElement("link");
144	          link.rel = "stylesheet";
145	          link.href = href;
146	          link.addEventListener("load", () => resolve());
147	          link.addEventListener("error", () => resolve());
148	          document.head.appendChild(link);
149	        }),
150	    ),
151	  );
152	
153	  // The whole demo (toolbar chrome + rendered result) follows the site's theme, chosen by the palette
154	  // selector in the docs header and pushed here via `pantoken-demo-theme`. The one multi-theme token
155	  // sheet (in cssUrls) covers every theme, so switching is just toggling the `data-pantoken-theme`
156	  // attribute — on this chrome document, and on the result's `<html>` (stamped in render). Starts on the
157	  // default until the host replies to our request below.
158	  let currentTheme = "rebrand";
159	  document.documentElement.dataset.pantokenTheme = currentTheme;
160	  const setTheme = (name: string): void => {
161	    if (name === currentTheme) return;
162	    currentTheme = name;
163	    document.documentElement.dataset.pantokenTheme = name;
164	    render();
165	  };
166	
167	  let sourceText: string;
168	  try {
169	    // Revalidate so an edited demo snippet isn't served stale from cache.
170	    const response = await fetch(srcUrl, { cache: "no-cache" });
171	    if (!response.ok) throw new Error(`HTTP ${response.status}`);
172	    sourceText = await response.text();
173	  } catch (error) {
174	    fail(`Failed to load demo: ${String(error)}`);
175	    return;
176	  }
177	
178	  let css = "";
179	  let js = "";
180	  const html = sourceText
181	    .replace(/<style[^>]*>([\s\S]*?)<\/style>/gi, (_match, body: string) => {
182	      css += `${body.trim()}\n`;
183	      return "";
184	    })
