218	  // The code panes start empty (so the tabs work); Shiki fills them in the background — see
219	  // `buildEditors`. The read-only viewer reads like the example's code fence: no gutter, no editing,
220	  // line wrapping handled in runner.css.
221	  const holders = new Map<PartKey, HTMLElement>();
222	  for (const key of parts) {
223	    const holder = document.createElement("div");
224	    holder.className = "runner__editor";
225	    codeArea.appendChild(holder);
226	    holders.set(key, holder);
227	  }
228	
229	  // The code follows the toggle's scheme (`effectiveDark`); flip the Shiki color variables via a class.
230	  const applyEditorScheme = (): void => {
231	    document.documentElement.classList.toggle("code-dark", effectiveDark());
232	  };
233	  applyEditorScheme();
234	
235	  // Load Shiki and highlight the code panes — kept OFF the critical path (not awaited before the reveal),
236	  // so the Result view appears without waiting on the grammars to download and parse. Uses the same
237	  // themes the docs' `@example` fences do; a `.copied` copy button rides along on each pane.
238	  const buildEditors = async (): Promise<void> => {
239	    if (!parts.length) return;
240	    const [githubLight, githubDark] = await Promise.all([
241	      import("@shikijs/themes/github-light").then((m) => m.default),
242	      import("@shikijs/themes/github-dark").then((m) => m.default),
243	    ]);
244	    const highlighter = await createHighlighterCore({
245	      themes: [githubLight, githubDark],
246	      langs: await Promise.all(parts.map((key) => langLoaders[key]())),
247	      engine: createJavaScriptRegexEngine(),
248	    });
