250	      const holder = holders.get(key);
251	      if (!holder) continue;
252	      holder.innerHTML = highlighter.codeToHtml(code[key], {
253	        lang: langId[key],
254	        themes: { light: "github-light", dark: "github-dark" },
255	        defaultColor: false,
256	      });
257	      holder.appendChild(createCopyButton(code[key]));
258	    }
259	    // The panes just gained content; if a code tab is showing, grow the player to fit it.
260	    applyAutoHeight();
261	    reportSize();
262	  };
263	
264	  function render(): void {
265	    const scheme = schemeName();
266	    // The chrome stays on the inherited (page) scheme; only the rendered result follows the toggle.
267	    document.documentElement.style.colorScheme = isDark() ? "dark" : "light";
268	    const links = cssUrls.map((href) => `<link rel="stylesheet" href="${href}">`).join("");
269	    // The markup can be arbitrary (edited live, or a shared ?src= URL), so sanitize it — strip
270	    // scripts and event handlers, keep HTML + SVG. The demo's own JS runs from the JS tab below.
271	    const safeHtml = DOMPurify.sanitize(original.html, {
272	      USE_PROFILES: { html: true, svg: true, svgFilters: true },
273	    });
274	    // A comfortable result gutter (base.css resets body margin to 0). Declared before the demo's own
275	    // <style> so a demo can override it, and with a plain `body` selector so it beats base's :where().
276	    const gutter = `<style>body{padding:var(--instui-spacing-space-md, 1rem)}</style>`;
277	    // Report the rendered content's height to the runner (its parent) so the runner can size itself —
278	    // and, in turn, the embedding demo figure — to the demo instead of a fixed box. Fires on load and
279	    // whenever the content reflows (fonts, images, the demo's own JS).
280	    //
281	    // Measure the BODY box, not <html>: an iframe's <html> stretches to fill the frame's viewport, so
282	    // `documentElement.scrollHeight` reports the frame height, not the content — a feedback loop that
283	    // never shrinks to the demo. The body hugs its own content, so it's the true height to report.
284	    // It also listens for `pantoken-demo-freeze`: while the reader drags the runner's resize handle, the
285	    // runner asks it to hide its own scrollbar so it doesn't flicker as the height recomputes.
286	    const sizeReporter = `<script>(function(){var p=window.parent;function r(){p.postMessage({type:"pantoken-demo-result-size",height:Math.ceil(document.body.getBoundingClientRect().height)},"*");}addEventListener("load",r);if(window.ResizeObserver){new ResizeObserver(r).observe(document.body);}addEventListener("message",function(e){if(e&&e.data&&e.data.type==="pantoken-demo-freeze"){document.documentElement.style.overflow=e.data.value?"hidden":"";}});r();})()</script>`;
