290	      `<script>${original.js}</script>${sizeReporter}</body></html>`;
291	  }
292	
293	  // Swap the code's colors (and re-render the result) when the embedding page toggles light/dark.
294	  function applyTheme(): void {
295	    applyEditorScheme();
296	    render();
297	  }
298	
299	  let activeCode: PartKey | null = parts[0] ?? null;
300	  const showEditor = (key: PartKey | null): void => {
301	    for (const [holderKey, holder] of holders) {
302	      holder.toggleAttribute("data-active", holderKey === key);
303	    }
304	  };
305	  const select = (name: string): void => {
306	    for (const input of tablist.querySelectorAll<HTMLInputElement>('input[type="radio"]')) {
307	      input.checked = input.value === name;
308	    }
309	    if (name === "result") {
310	      runner.classList.add("runner--show-result");
311	    } else {
312	      runner.classList.remove("runner--show-result");
313	      activeCode = name as PartKey;
314	      showEditor(activeCode);
315	    }
316	    // Re-size the player for the new view (a code tab adds the editor's height above the result). Run
317	    // now, and again next frame once the just-shown editor has laid out and its scrollHeight is accurate.
318	    applyAutoHeight();
319	    reportSize();
320	    requestAnimationFrame(() => {
321	      applyAutoHeight();
322	      reportSize();
323	    });
324	  };
325	
326	  // Size the player, then tell the embedding figure how tall to make its iframe. The body's default
327	  // height hugs the demo but caps at 30rem; `resize: vertical` (runner.css) lets the reader drag it past
328	  // that, and once they do we latch `userResized` and stop auto-sizing, so a tab switch or theme change
329	  // doesn't snap their height back. We always report `toolbar + body` so the figure iframe mirrors the
330	  // runner exactly — a standalone tab (no parent) has nothing to size, so it skips the report.
331	  const MAX_DEFAULT_REM = 30;
332	  let resultContentHeight = 0;
333	  let userResized = false;
334	  let lastAutoHeight = -1;
335	
336	  // Report the whole runner's height (toolbar + the body and its margin), not just `toolbar + body`, so
337	  // the iframe mirrors it exactly — otherwise the body's margin is clipped and the resize grip with it.
338	  // Suppressed while booting: the host holds the stable spinner box until `reveal()` reports the real
339	  // height.
340	  const reportSize = (): void => {
341	    if (window.parent === window || booting) return;
342	    window.parent.postMessage(
343	      { type: "pantoken-demo-size", height: Math.ceil(runner.getBoundingClientRect().height) },
344	      "*",
345	    );
346	  };
347	  // Coalesce the rapid reports during a drag into one per frame.
348	  let reportScheduled = false;
349	  const scheduleReport = (): void => {
350	    if (reportScheduled) return;
351	    reportScheduled = true;
352	    requestAnimationFrame(() => {
353	      reportScheduled = false;
354	      reportSize();
355	    });
356	  };
