371	  // rendered height and stack the code above it (auto-fit to the code's own height), so the player grows
372	  // to fit both rather than halving a fixed box. Either default is still draggable.
373	  const px = (value: string): number => Number.parseFloat(value) || 0;
374	  const defaultBodyHeight = (): number => {
375	    const remPx = px(getComputedStyle(document.documentElement).fontSize) || 16;
376	    const cap = Math.max(0, Math.floor(MAX_DEFAULT_REM * remPx - chromeHeight()));
377	    const bs = getComputedStyle(body);
378	    const bodyExtra =
379	      px(bs.paddingTop) + px(bs.paddingBottom) + px(bs.borderTopWidth) + px(bs.borderBottomWidth);
380	    // The result pane's rendered height: hug the demo, capped so the result view stays within the cap.
381	    const resultView = Math.min(resultContentHeight, Math.max(0, cap - bodyExtra));
382	    if (runner.classList.contains("runner--show-result")) return resultView + bodyExtra;
