401	    runner.classList.toggle("runner--resizing", on);
402	    resultFrame.contentWindow?.postMessage({ type: "pantoken-demo-freeze", value: on }, "*");
403	  };
404	  let resizeSettle: ReturnType<typeof setTimeout> | undefined;
405	
406	  // A body height change we didn't make (beyond a rounding fuzz) is the reader dragging the handle:
407	  // latch it so we stop overriding their choice, hide the scrollbars for the drag, and report (throttled
408	  // to one per frame) so the host iframe tracks along.
409	  if (window.ResizeObserver) {
410	    new ResizeObserver(() => {
411	      const height = Math.round(body.getBoundingClientRect().height);
412	      if (!userResized && lastAutoHeight >= 0 && Math.abs(height - lastAutoHeight) > 3) {
413	        userResized = true;
414	      }
415	      if (userResized) {
416	        setResizing(true);
417	        clearTimeout(resizeSettle);
418	        resizeSettle = setTimeout(() => setResizing(false), 150);
419	      }
420	      scheduleReport();
