422	  }
423	
424	  const addTab = (name: string, label: string): void => {
425	    // A segmented radio: one label per view, single-select via the shared name — the checked radio is
426	    // the active tab.
427	    const wrapper = document.createElement("label");
428	    wrapper.className = "instui-radio -variant-toggle -size-sm";
429	    const input = document.createElement("input");
430	    input.type = "radio";
431	    input.name = "runner-view";
432	    input.value = name;
433	    input.addEventListener("change", () => {
434	      if (input.checked) select(name);
435	    });
436	    wrapper.append(input, document.createTextNode(` ${label}`));
437	    tablist.appendChild(wrapper);
438	  };
