451	  // Two things gate the reveal-ready render: the host's theme reply (so the first render is in the right
452	  // theme — no post-reveal re-render flash) and the first result-size report (the demo has rendered and
453	  // measured). Both resolve in the message handler below.
454	  let resolveFirstSize: (() => void) | undefined;
455	  const firstResultSize = new Promise<void>((resolve) => {
456	    resolveFirstSize = resolve;
457	  });
458	  let resolveTheme: (() => void) | undefined;
459	  const themeReady = new Promise<void>((resolve) => {
460	    resolveTheme = resolve;
461	  });
462	
463	  // The docs header drives this runner: `pantoken-demo-theme` picks the token theme (rebrand/canvas/…)
