485	  // Ask the host which theme to render, then render once it replies (or after a short wait). Standalone
486	  // (no parent) has nothing to ask, so proceed straight away.
487	  if (window.parent && window.parent !== window) {
488	    window.parent.postMessage({ type: "pantoken-demo-request-theme" }, "*");
489	  } else {
