49	 * Build a resolver that expands `var(--x)` references to concrete leaf values against `base` (plus
50	 * any `overrides`). With `mode` it collapses `light-dark()` to that branch; without, it leaves
51	 * `light-dark()` in place.
52	 *
53	 * @param base - The token set to resolve references against.
54	 * @param options - {@link ResolveOptions}.
55	 * @returns A function that resolves a value string.
56	 *
57	 * @example Expand a reference chain to its concrete leaf
58	 * ```ts
59	 * import { makeResolver } from "@pantoken/utils";
60	 * import type { Token } from "@pantoken/model";
61	 *
62	 * const ir: Token[] = [
63	 *   { name: "--instui-leaf", syntax: "<color>", inherits: true, value: "#0374B5" },
64	 *   { name: "--instui-brand", syntax: "*", inherits: true, value: "var(--instui-leaf)" },
65	 * ];
66	 *
67	 * const resolve = makeResolver(ir);
68	 * resolve("var(--instui-brand)"); // → "#0374B5"
69	 * ```
70	 *
71	 * @example Collapse light-dark() with a mode, or keep it without one
72	 * ```ts
73	 * import { makeResolver } from "@pantoken/utils";
74	 * import type { Token } from "@pantoken/model";
75	 *
76	 * const ir: Token[] = [
77	 *   { name: "--instui-bg", syntax: "*", inherits: true, value: "light-dark(#fff, #000)" },
78	 * ];
79	 *
80	 * makeResolver(ir)("var(--instui-bg)");                 // → "light-dark(#fff, #000)"
81	 * makeResolver(ir, { mode: "light" })("var(--instui-bg)"); // → "#fff"
82	 * makeResolver(ir, { mode: "dark" })("var(--instui-bg)");  // → "#000"
83	 * ```
84	 *
85	 * @example Layer overrides that win on name collisions
86	 * ```ts
87	 * import { makeResolver } from "@pantoken/utils";
88	 * import type { Token } from "@pantoken/model";
89	 *
90	 * const ir: Token[] = [
91	 *   { name: "--instui-leaf", syntax: "<color>", inherits: true, value: "#0374B5" },
92	 *   { name: "--instui-brand", syntax: "*", inherits: true, value: "var(--instui-leaf)" },
93	 * ];
94	 * const overrides: Token[] = [
95	 *   { name: "--instui-leaf", syntax: "<color>", inherits: true, value: "#000" },
96	 * ];
97	 *
98	 * makeResolver(ir, { overrides })("var(--instui-brand)"); // → "#000"
99	 * ```
100	 */
101	export function makeResolver(
102	  base: readonly Token[],
103	  options: ResolveOptions = {},
104	): (value: string) => string {
105	  const map = new Map(base.map((t) => [t.name, t.value]));
106	  for (const t of options.overrides ?? []) map.set(t.name, t.value);
107	
108	  const pickMode = (value: string): string => {
109	    if (!options.mode) return value;
110	    const m = LIGHT_DARK_RE.exec(value.trim());
111	    return m ? (options.mode === "light" ? m[1] : m[2]) : value;
112	  };
113	
114	  const expand = (value: string, depth: number): string => {
115	    const picked = pickMode(value);
116	    if (depth >= MAX_DEPTH || !picked.includes("var(")) return picked;
117	    // Fresh regex per call — a shared /g regex would corrupt its lastIndex across these recursive
118	    // replace() calls.
119	    return picked.replace(new RegExp(VAR_SOURCE, "g"), (whole, name: string) => {
120	      const inner = map.get(name);
121	      return inner === undefined ? whole : expand(inner, depth + 1);
122	    });
123	  };
124	
125	  return (value) => expand(value, 0);
126	}
