129	 * Resolve every token's value against the set (see {@link makeResolver}), keyed by name.
130	 *
131	 * @example Resolve a whole IR to a name → value map
132	 * ```ts
133	 * import { resolveTokens } from "@pantoken/utils";
134	 * import type { Token } from "@pantoken/model";
135	 *
136	 * const ir: Token[] = [
137	 *   { name: "--instui-leaf", syntax: "<color>", inherits: true, value: "#0374B5" },
138	 *   { name: "--instui-brand", syntax: "*", inherits: true, value: "var(--instui-leaf)" },
139	 *   { name: "--instui-bg", syntax: "*", inherits: true, value: "light-dark(#fff, #000)" },
140	 * ];
141	 *
142	 * const byName = resolveTokens(ir, { mode: "dark" });
143	 * byName.get("--instui-brand"); // → "#0374B5"
144	 * byName.get("--instui-bg");    // → "#000"
145	 * ```
146	 */
147	export function resolveTokens(
148	  base: readonly Token[],
149	  options: ResolveOptions = {},
150	): Map<string, string> {
151	  const resolve = makeResolver(base, options);
152	  return new Map(base.map((t) => [t.name, resolve(t.value)]));
153	}
154	
155	/**
156	 * Convert a kebab-case string to camelCase (`color-background-brand` → `colorBackgroundBrand`).
157	 *
158	 * @example
159	 * ```ts
160	 * import { camelCase } from "@pantoken/utils";
161	 *
162	 * camelCase("color-background-brand"); // → "colorBackgroundBrand"
163	 * ```
164	 */
165	export function camelCase(kebab: string): string {
166	  return kebab.replace(/-([a-z0-9])/g, (_, c: string) => c.toUpperCase());
167	}
